#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> adj(n + 1, -1);
    vector<bool> visited(n + 1, false);

    for (int i = 0; i < n; ++i) {
        adj[i] = (i * k) % n;
    }

    function<void(int)> depth_first_search = [&](int node) {
        visited[node] = true;
        while (!visited[adj[node]]) {
            node = adj[node];
            visited[node] = true;
        }
    };

    const long long MOD = 1000000007;
    int component_counter = 0;

    for (int i = 1; i < n; ++i) {
        if (!visited[i]) {
            depth_first_search(i);
            component_counter++;
        }
    }

    if (k == 1) {
        long long result = 1;
        for (int i = 0; i < n; ++i) {
            result = (result * n) % MOD;
        }
        cout << result << "\n";
    } else {
        long long result = 1;
        for (int i = 0; i < component_counter; ++i) {
            result = (result * n) % MOD;
        }
        cout << result << "\n";
    }

    return 0;
}
